static String getDescriptionPart(DependencyType type, String description) {

   String header = getDescriptionHeader(type);
   StringBuilder descriptionPart = new StringBuilder();
   if (description.length() > 0) {
      descriptionPart.append("<br/><br/>");
      if (header != null) {
         descriptionPart.append(header);
      }
      descriptionPart.append(description);
   }
   return descriptionPart.toString();
}

@Override
public void examineDetail(JavaSource javaSource, Scanner scanner, String currentToken, DependencyType type) {
   String token = jumpOverJavaToken(currentToken, scanner);
   // possible tokens now are e.g. Principal, Greeter(PhraseBuilder, Event<Person>, AsyncService ...
   if (token.indexOf('(') > - 1) {
      // Greeter(PhraseBuilder becomes PhraseBuilder
      token = token.substring(token.indexOf('(') + 1);
   }
   String className = jumpOverJavaToken(token, scanner);
   if (!className.contains("Instance<") && !className.contains("Event<")) {
      className = cleanupGeneric(className);
      createDependency(className, type, javaSource);
   }
}

@Override
protected DependencyType getTypeFromToken(String token) {
   DependencyType type = null;
   if (token.contains("@Inject")) {
      type = DependencyType.INJECT;
   }
   return type;
}

@Override
protected DependencyType getTypeFromToken(String token) {
   DependencyType type = null;
   // Identify @Produces form Inject (@Produces form WS is @Produces(...)
   // Inject: http://docs.oracle.com/javaee/6/api/javax/enterprise/inject/Produces.html
   // WS: http://docs.oracle.com/javaee/6/api/javax/ws/rs/Produces.html
   if (token.contains("@Produces") && !token.contains("@Produces(")) {
      type = DependencyType.PRODUCES;
   }
   return type;
}

@Override
public void examineDetail(JavaSource javaSource, Scanner scanner, String currentToken, DependencyType type) {
   String className = jumpOverJavaToken(currentToken, scanner);
   className = cleanupGeneric(className);
   createDependency(className, type, javaSource);
}

