public String getSourceCodeWithoutComments() {
   Scanner scanner = new Scanner(sourceCode);
   scanner.useDelimiter("[\n]+");
   StringBuilder sourceCodeWithoutComments = new StringBuilder();
   boolean isInCommentBlock = false;
   while (scanner.hasNext()) {
      String token = scanner.next();
      if (token.trim().startsWith("/*")) {
         isInCommentBlock = true;
      }
      if (!token.trim().startsWith("//") && !isInCommentBlock) {
         sourceCodeWithoutComments.append(token);
         sourceCodeWithoutComments.append("\n");
      }
      if (token.trim().startsWith("*/")) {
         isInCommentBlock = false;
      }
   }

   return cleanAllEqualsWithSpaces(sourceCodeWithoutComments.toString());
}

protected static String getClassBody(String sourceCode) {
   StringBuilder classBody = new StringBuilder();
   boolean isInBodyNow = false;
   try (Scanner scanner = new Scanner(sourceCode)) {
      scanner.useDelimiter("[\n]+");
      while (scanner.hasNext()) {
         String token = scanner.next();
         if (!isInBodyNow) {
            if (token.contains("class ")) {
               isInBodyNow = true;
            }
         } else {
            classBody.append(token).append("\n");
         }
      }
   }

   return classBody.toString();
}

protected static String cleanPrimitives(String className) {
   String cleanedClassName = className;
   String arrayToken = "";
   // e.g. int[] should be Integer[]
   if (className.indexOf('[') > -1) {
      cleanedClassName = className.substring(0, className.indexOf('['));
      arrayToken = className.substring(className.indexOf('['));
   }
   switch (cleanedClassName) {
      case "boolean":
         cleanedClassName = "Boolean";
         break;
      case "char":
         cleanedClassName = "Character";
         break;
      case "byte":
         cleanedClassName = "Byte";
         break;
      case "short":
         cleanedClassName = "Short";
         break;
      case "int":
         cleanedClassName = "Integer";
         break;
      case "long":
         cleanedClassName = "Long";
         break;
      case "float":
         cleanedClassName = "Float";
         break;
      case "double":
         cleanedClassName = "Double";
         break;
   }
   return cleanedClassName + arrayToken;
}

void findAndSetPackage() {
   Scanner scanner = Examiner.getSourceCodeScanner(getSourceCode());
   while (scanner.hasNext()) {
      String token = scanner.next();
      if (getPackagePath() == null && token.equals("package")) {
         if (!scanner.hasNext()) {
            throw new IllegalArgumentException("Insufficient number of tokens to set package in " + this.getJavaFile());
         }
         token = scanner.next();
         if (token.endsWith(";")) {
            String foundPackagePath = token.substring(0, token.indexOf(';'));
            setPackagePath(foundPackagePath);
         }
      }
   }
}

