@Override
@SuppressWarnings("unchecked") // Checks if T is not Optional and returns early
public <T> TypeAdapter<T> create(Gson gson, TypeToken<T> type) {
    if (type.getRawType() == Optional.class && type.getType() instanceof ParameterizedType) {
        var optionalType = (ParameterizedType) type.getType();

        return (TypeAdapter<T>) new OptionalTypeAdapter(gson, optionalType.getActualTypeArguments()[0]);
    }

    return null;
}

public Optional<Response> sendRequest(Request req) throws ConnectionException {
    Objects.requireNonNull(req);

    var res = send(gson.toJson(req));

    if (req instanceof Notification)
        return Optional.empty();

    return Optional.of(gson.fromJson(res, Response.class));
}

@Override
@SuppressWarnings("unchecked")
public <T> TypeAdapter<T> create(Gson gson, TypeToken<T> type) {
    if (Id.class.isAssignableFrom(type.getRawType()))
        return (TypeAdapter<T>) IdTypeAdapter.instance();

    if (Parameters.class.isAssignableFrom(type.getRawType()))
        return (TypeAdapter<T>) ParameterTypeAdapter.instance();

    return null;
}

