@Override
public int hashCode() {
    int result = table != null ? table.hashCode() : 0;
    result = 31 * result + (property != null ? property.hashCode() : 0);
    result = 31 * result + (column != null ? column.hashCode() : 0);
    result = 31 * result + (javaType != null ? javaType.hashCode() : 0);
    result = 31 * result + (jdbcType != null ? jdbcType.hashCode() : 0);
    result = 31 * result + (typeHandler != null ? typeHandler.hashCode() : 0);
    result = 31 * result + (id ? 1 : 0);
    result = 31 * result + (identity ? 1 : 0);
    result = 31 * result + (generator != null ? generator.hashCode() : 0);
    result = 31 * result + (orderBy != null ? orderBy.hashCode() : 0);
    return result;
}

public EntityField(Field field, PropertyDescriptor propertyDescriptor) {
    if (field != null) {
        this.field = field;
        this.name = field.getName();
        this.javaType = field.getType();
    }
    if (propertyDescriptor != null) {
        this.name = propertyDescriptor.getName();
        this.setter = propertyDescriptor.getWriteMethod();
        this.getter = propertyDescriptor.getReadMethod();
        this.javaType = propertyDescriptor.getPropertyType();
    }
}

@Override
public List<EntityField> getFields(Class<?> entityClass) {
    List<EntityField> fields = _getFields(entityClass, null, null);
    List<EntityField> properties = getProperties(entityClass);
    Set<EntityField> usedSet = new HashSet<EntityField>();
    for (EntityField field : fields) {
        for (EntityField property : properties) {
            if (!usedSet.contains(property) && field.getName().equals(property.getName())) {
                //泛型的情况下通过属性可以得到实际的类型
                field.setJavaType(property.getJavaType());
                break;
            }
        }
    }
    return fields;
}

public String getColumnHolder(String entityName, String suffix, String separator) {
    StringBuffer sb = new StringBuffer("#{");
    if (StringUtil.isNotEmpty(entityName)) {
        sb.append(entityName);
        sb.append(".");
    }
    sb.append(this.property);
    if (StringUtil.isNotEmpty(suffix)) {
        sb.append(suffix);
    }
    //如果 null 被当作值来传递，对于所有可能为空的列，JDBC Type 是需要的
    if (this.jdbcType != null) {
        sb.append(", jdbcType=");
        sb.append(this.jdbcType.toString());
    }
    //为了以后定制类型处理方式，你也可以指定一个特殊的类型处理器类，例如枚举
    if (this.typeHandler != null) {
        sb.append(", typeHandler=");
        sb.append(this.typeHandler.getCanonicalName());
    }
    //3.4.0 以前的 mybatis 无法获取父类中泛型的 javaType，所以如果使用低版本，就需要设置 useJavaType = true
    //useJavaType 默认 false,没有 javaType 限制时，对 ByPrimaryKey 方法的参数校验就放宽了，会自动转型
    if (useJavaType && !this.javaType.isArray()) {//当类型为数组时，不设置javaType#103
        sb.append(", javaType=");
        sb.append(javaType.getCanonicalName());
    }
    sb.append("}");
    if (StringUtil.isNotEmpty(separator)) {
        sb.append(separator);
    }
    return sb.toString();
}

@Override
public List<EntityField> getProperties(Class<?> entityClass) {
    List<EntityField> entityFields = new ArrayList<EntityField>();
    BeanInfo beanInfo = null;
    try {
        beanInfo = Introspector.getBeanInfo(entityClass);
    } catch (IntrospectionException e) {
        throw new MapperException(e);
    }
    PropertyDescriptor[] descriptors = beanInfo.getPropertyDescriptors();
    for (PropertyDescriptor desc : descriptors) {
        if (!"class".equals(desc.getName())) {
            entityFields.add(new EntityField(null, desc));
        }
    }
    return entityFields;
}

public boolean isAnnotationPresent(Class<? extends Annotation> annotationClass) {
    boolean result = false;
    if (field != null) {
        result = field.isAnnotationPresent(annotationClass);
    }
    if (!result && setter != null) {
        result = setter.isAnnotationPresent(annotationClass);
    }
    if (!result && getter != null) {
        result = getter.isAnnotationPresent(annotationClass);
    }
    return result;
}

public <T extends Annotation> T getAnnotation(Class<T> annotationClass) {
    T result = null;
    if (field != null) {
        result = field.getAnnotation(annotationClass);
    }
    if (result == null && setter != null) {
        result = setter.getAnnotation(annotationClass);
    }
    if (result == null && getter != null) {
        result = getter.getAnnotation(annotationClass);
    }
    return result;
}

