public static List<Field> getAllFieldsList(final Class<?> cls) {
    Validate.isTrue(cls != null, "The class must not be null");
    final List<Field> allFields = new ArrayList<>();
    Class<?> currentClass = cls;
    while (currentClass != null) {
        final Field[] declaredFields = currentClass.getDeclaredFields();
        Collections.addAll(allFields, declaredFields);
        currentClass = currentClass.getSuperclass();
    }
    return allFields;
}

public static List<Field> getFieldsListWithAnnotation(final Class<?> cls, final Class<? extends Annotation> annotationCls) {
    Validate.isTrue(annotationCls != null, "The annotation class must not be null");
    final List<Field> allFields = getAllFieldsList(cls);
    final List<Field> annotatedFields = new ArrayList<>();
    for (final Field field : allFields) {
        if (field.getAnnotation(annotationCls) != null) {
            annotatedFields.add(field);
        }
    }
    return annotatedFields;
}

public static Field[] getFieldsWithAnnotation(final Class<?> cls, final Class<? extends Annotation> annotationCls) {
    final List<Field> annotatedFieldsList = getFieldsListWithAnnotation(cls, annotationCls);
    return annotatedFieldsList.toArray(new Field[annotatedFieldsList.size()]);
}

public static String append(final CharSequence url, final Object... params) {
  final String baseUrl = url.toString();
  if (params == null || params.length == 0)
    return baseUrl;

  if (params.length % 2 != 0)
    throw new IllegalArgumentException(
        "Must specify an even number of parameter names/values");

  final StringBuilder result = new StringBuilder(baseUrl);

  addPathSeparator(baseUrl, result);
  addParamPrefix(baseUrl, result);

  addParam(params[0], params[1], result);

  for (int i = 2; i < params.length; i += 2) {
    result.append('&');
    addParam(params[i], params[i + 1], result);
  }

  return result.toString();
}

private static StringBuilder addParam(final Object key, Object value,
    final StringBuilder result) {
  if (value != null && value.getClass().isArray())
    value = arrayToList(value);

  if (value instanceof Iterable<?>) {
    Iterator<?> iterator = ((Iterable<?>) value).iterator();
    while (iterator.hasNext()) {
      result.append(key);
      result.append("[]=");
      Object element = iterator.next();
      if (element != null)
        result.append(element);
      if (iterator.hasNext())
        result.append("&");
    }
  } else {
    result.append(key);
    result.append("=");
    if (value != null)
      result.append(value);
  }

  return result;
}

private static StringBuilder addParamPrefix(final String baseUrl,
    final StringBuilder result) {
  // Add '?' if missing and add '&' if params already exist in base url
  final int queryStart = baseUrl.indexOf('?');
  final int lastChar = result.length() - 1;
  if (queryStart == -1)
    result.append('?');
  else if (queryStart < lastChar && baseUrl.charAt(lastChar) != '&')
    result.append('&');
  return result;
}

