public AISMessageParser(AISSentence... sentences) {
    int index = 1;
    for (AISSentence s : sentences) {
        if (s.isFragmented() && s.getFragmentNumber() != index++) {
            throw new IllegalArgumentException("Incorrect order of AIS sentences");
        }
        this.append(s.getPayload(), s.getFragmentNumber(), s.getFillBits());
    }
    this.decoder = new Sixbit(this.message, this.fillBits);
}

void append(String fragment, int fragmentIndex, int fillBits) {
    if (fragment == null || fragment.isEmpty()) {
        throw new IllegalArgumentException("Message fragment cannot be null or empty");
    }
    if (fragmentIndex < 1 || fragmentIndex != (lastFragmentNr + 1)) {
        throw new IllegalArgumentException("Invalid fragment index or sequence order");
    }
    if (fillBits < 0) {
        throw new IllegalArgumentException("Fill bits cannot be negative");
    }
    this.lastFragmentNr = fragmentIndex;
    this.message += fragment;
    this.fillBits = fillBits; // we always use the last
}

protected AISMessageParser(Sixbit sb) {
    if (sb.length() <= 0) {
        throw new IllegalArgumentException("Sixbit decoder is empty!");
    }
    this.decoder = sb;
}

Sixbit getSixbit() {
    if (decoder == null && message.isEmpty()) {
        throw new IllegalStateException("Message is empty!");
    }
    return decoder == null ? new Sixbit(message, fillBits) : decoder;
}

public SentenceParser(String nmea) {

	if (!SentenceValidator.isValid(nmea)) {
		String msg = String.format("Invalid data [%s]", nmea);
		throw new IllegalArgumentException(msg);
	}

	beginChar = nmea.charAt(0);
	talkerId = TalkerId.parse(nmea);
	sentenceId = SentenceId.parseStr(nmea);

	int begin = nmea.indexOf(Sentence.FIELD_DELIMITER) + 1;
	int end = Checksum.index(nmea);

	String csv = nmea.substring(begin, end);
	String[] values = csv.split(String.valueOf(FIELD_DELIMITER), -1);
	fields.addAll(Arrays.asList(values));
}

protected SentenceParser(String nmea, String type) {
	this(nmea);
	if (type == null || "".equals(type)) {
		throw new IllegalArgumentException(
			"Sentence type must be specified.");
	}
	String sid = getSentenceId();
	if (!sid.equals(type)) {
		String ptrn = "Sentence id mismatch; expected [%s], found [%s].";
		String msg = String.format(ptrn, type, sid);
		throw new IllegalArgumentException(msg);
	}
}

public static String parseStr(String nmea) {

    if (!SentenceValidator.isSentence(nmea)) {
        throw new IllegalArgumentException("String is not a sentence");
    }

    String id = null;
    if (nmea.startsWith("$P")) {
        id = nmea.substring(2, nmea.indexOf(','));
    } else {
        id = nmea.substring(3, nmea.indexOf(','));
    }
    return id;
}

public static TalkerId parse(String nmea) {

	if (!SentenceValidator.isSentence(nmea)) {
		throw new IllegalArgumentException("String is not a sentence");
	}

	String tid = "";
	if (nmea.startsWith("$P")) {
		tid = "P";
	} else {
		tid = nmea.substring(1, 3);
	}
	return TalkerId.valueOf(tid);
}

