    requireNonNull(nmeaMessages);
    check(nmeaMessages);
    this.nmeaMessages = nmeaMessages;
    this.bitString = new WeakReference<>(bitString);
    AISMessageType nmeaMessageType = decodeMessageType();
    if (getMessageType() != nmeaMessageType) {
