  progress(null);
  if (output == null)
    return this;
  if (multipart)
    output.write(CRLF + "--" + BOUNDARY + "--" + CRLF);
  if (ignoreCloseExceptions)
    try {
      output.close();
    } catch (IOException ignored) {
      // Ignored
    }
  else
    output.close();
  output = null;
  return this;
}

