JsonToStringStyle() {
    super();

    this.setUseClassName(false);
    this.setUseIdentityHashCode(false);

    this.setContentStart("{");
    this.setContentEnd("}");

    this.setArrayStart("[");
    this.setArrayEnd("]");

    this.setFieldSeparator(",");
    this.setFieldNameValueSeparator(":");

    this.setNullText("null");

