private static boolean isValidDefault(Schema schema, JsonNode defaultValue) {
  if (defaultValue == null)
    return false;
  switch (schema.getType()) {
  case STRING:
  case BYTES:
  case ENUM:
  case FIXED:
    return defaultValue.isTextual();
  case INT:
  case LONG:
  case FLOAT:
  case DOUBLE:
    return defaultValue.isNumber();
  case BOOLEAN:
    return defaultValue.isBoolean();
  case NULL:
    return defaultValue.isNull();
  case ARRAY:
    if (!defaultValue.isArray())
      return false;
    for (JsonNode element : defaultValue)
      if (!isValidDefault(schema.getElementType(), element))
        return false;
    return true;
  case MAP:
    if (!defaultValue.isObject())
      return false;
    for (JsonNode value : defaultValue)
      if (!isValidDefault(schema.getValueType(), value))
        return false;
    return true;
  case UNION: // union default: first branch
    return isValidDefault(schema.getTypes().get(0), defaultValue);
  case RECORD:
    if (!defaultValue.isObject())
      return false;
    for (Field field : schema.getFields())
      if (!isValidDefault(field.schema(),
          defaultValue.has(field.name()) ? defaultValue.get(field.name()) : field.defaultValue()))
        return false;
    return true;
  default:
    return false;
  }
}

