        break;
    case 1:
        out[0] = ENCODING_TABLE[(a>>2)&0x3F];
        out[1] = ENCODING_TABLE[(a<<4)&0x3F];
        out[2] = '=';
        out[3] = '=';
        super.out.write(out,0,4);
        remaining = 0;
        break;
    case 2:
        out[0] = ENCODING_TABLE[(a>>2)&0x3F];
        out[1] = ENCODING_TABLE[((a<<4)|(b>>4))&0x3F];
        out[2] = ENCODING_TABLE[(b<<2)&0x3F];
        out[3] = '=';
        super.out.write(out,0,4);
        remaining = 0;
        break;
    default:
        throw new AssertionError();
    }
    super.flush();
