public static Type resolveReturnType(Type baseType, Type overridingType) {
  if (baseType instanceof Class && overridingType instanceof Class &&
      ((Class<?>) baseType).isAssignableFrom((Class<?>) overridingType)) {
    // NOTE: javac generates multiple same methods for multiple inherited generic interfaces
    return overridingType;
  }
  if (baseType instanceof Class && overridingType instanceof ParameterizedType) {
    // NOTE: javac will generate multiple methods with different return types
    // base interface declares generic method, override declares parameterized generic method
    return overridingType;
  }
  if (baseType instanceof Class && overridingType instanceof TypeVariable) {
    // NOTE: javac will generate multiple methods with different return types
    // base interface declares non generic method, override declares generic method
    return overridingType;
  }
  return baseType;
}

public int find(int[] numbers, int position) {
  validateInput(numbers, position);
  Integer result = null;
  Map<Integer, Integer> counter = new HashMap<Integer, Integer>();
  for (int i : numbers) {
    if (counter.get(i) == null) {
      counter.put(i, 1);
    } else {
      counter.put(i, counter.get(i) + 1);
    }
  }
  for (Integer candidate : counter.keySet()) {
    if (counter.get(candidate) == position) {
      result = candidate;
      break;
    }
  }
  validateResult(result);
  return result;
}

private void validateInput(int[] numbers, int position) {
  if (numbers == null || position <= 0) {
    throw new IllegalArgumentException(
        "You can't pass null arrays or position values minor than 0 as parameter.");
  }
}

private void validateResult(Integer result) {
  if (result == null) {
    throw new IllegalArgumentException(
        "There are no elements repeated n times in the array passed as argument");
  }
}

def generate_id(self, what):
	if self.auto_id_type == "int":
		# increment and return
		self._auto_id_int += 1
		slug = self._auto_id_int
	elif self.auto_id_type == "int-per-segment":
		curr = self._auto_id_segments.get(what._uri_segment, -1)
		curr += 1
		self._auto_id_segments[what._uri_segment] = curr
		slug = self._auto_id_segments[what._uri_segment]
	elif self.auto_id_type == "int-per-type":
		t = type(what).__name__
		curr = self._auto_id_types.get(t, -1)
		curr += 1
		self._auto_id_types[t] = curr
		slug = self._auto_id_types[t]
	elif self.auto_id_type == "uuid":
		return "urn:uuid:%s" % uuid.uuid4()
	else:
		raise ConfigurationError("Unknown auto-id type")

	return self.base_url + what.__class__._uri_segment + "/" + str(slug)

def cache_hierarchy(self):
	""" For each class, walk up the hierarchy and cache the terms """
	# This will work with the existing code, as it will find it in the first
	# test of props on classhier[0], the loop will just terminate straight away

	for c in self._all_classes.values():
		new_hash = c._all_properties.copy()
		if len(c._classhier) > 1:
			for p in c._classhier[1:]:
				for (prop, info) in p._all_properties.items():
					if not prop in new_hash:
						new_hash[prop] = info
		c._all_properties = new_hash

def build_class(crmName, parent, vocabData):
	data = vocabData[crmName]
	name = str(data['className'])

	# check to see if we already exist
	# nb globals() here is only this module
	if name in globals():
		c = globals()[name]
		try:	
			c.__bases__ += (parent,)
		except:
			print("MRO FAILURE: %r --> %r + %r" % (c, c.__bases__, parent))
			raise
		return

	c = type(name, (parent,), {'__doc__': data['desc']})
	globals()[name] = c
	data['class'] = c
	if not ":" in crmName:
		c._type = "crm:%s" % crmName
	else:
		c._type = crmName
	c._uri_segment = name
	c._properties = {}
	c._all_properties = {}
	c._okayToUse = int(data['okay'])

	factory._all_classes[name] = c

	# Set up real properties
	for p in data['props']:
		name = p['name']
		if not ":" in name:
			name = "crm:%s" % name
		rng = p['range']
		ccname = p['propName']
		if p['inverse']:
			i = p['inverse']
			if i[0] == "P":
				invRdf = "crm:%s" % i
			else:
				invRdf = i
		else:
			invRdf = ""

		okay = p['okay']
		if not okay:
			okay = '1'
		okay = int(okay)
		mult = p['multiple']
		if not mult:
			mult = '0'
		mult = int(mult)

		# can't guarantee all classes have been built at this stage :(
		c._properties[ccname] = {"rdf": name, 
			"rangeStr": rng,
			"inverseRdf": invRdf,
			"okayToUse": okay,
			"multiple": mult}

	# Build subclasses
	for s in data['subs']:
		build_class(s, c, vocabData)

def process_tsv(fn):
	fh = codecs.open(fn, 'r', 'utf-8')
	lines = fh.readlines()[1:] # chomp header line
	fh.close()
	vocabData = {"rdf:Resource": 
		{"props": [], "label": "Resource", "className": "Resource", 
		"subs":[], "desc": "", "class": BaseResource, "okay": 1}}

	for l in lines:
		l = l[:-1] # chomp
		info= l.split('\t')
		name = info[0]	
		if info[1] == "class":
			data = {"subOf": info[5], "label": info[3], 'className': info[2],
				"desc": info[4], "class": None, "props": [], "subs": [], "okay": info[6]}
			vocabData[name] = data
		else:
			# property
			data = {"name": name, "subOf": info[5], "label": info[3], "propName": info[2],
			"desc": info[4], "range": info[7], "inverse": info[8], "okay": info[10], "multiple": info[11]}
			try:
				what = vocabData[info[6]]
			except:
				what = vocabData["rdf:Resource"]
			what["props"].append(data)

			koh = int(info[9])
			if koh != KEY_ORDER_DEFAULT:
				factory.key_order_hash[data['propName']] = koh
				factory.full_key_order_hash[data['name']] = koh

	# invert subclass hierarchy
	for k, v in vocabData.items():
		if k != "rdf:Resource":		
			sub = v['subOf']
			# | separated list
			for s in sub.split('|'):
				if s:
					try:
						vocabData[s]['subs'].append(k)
					except:
						pass
	return vocabData

