def _check_prop(self, which, value):
	val_props = self._factory.validate_properties
	val_profile = self._factory.validate_profile
	val_range = self._factory.validate_range
	for c in self._classhier:
		if which in c._all_properties:
			pinfo = c._all_properties[which]

			if val_profile:
				okay = pinfo.profile_okay					
				rdf = pinfo.predicate
				if not okay:
					raise ProfileError("Property '%s' / '%s' is configured to not be used" % (which, rdf), self)
				elif okay == 2:
					self._factory.maybe_warn("Property '%s' / '%s' is configured to warn on use" % (which, rdf))

			if val_range:
				rng = pinfo.range
				if rng is str:					
					return 1
				elif type(value) is BaseResource:
					# Allow direct instances of base resource anywhere
					# this is an override for external URIs
					return 2
				elif isinstance(value, rng):
					return 2
				else:
					raise DataError("Can't set '%s' on resource of type '%s' to '%r'" % (which, self._type, value), self)
			# Found it, but not validating range and either okay or not validating profile
			return 1
	if val_props:
		raise DataError("Can't set unknown field '%s' on resource of type '%s'" % (which, self._type), self)
	else:
		# Not validating ANYTHING
		return 1

def load_context(self, context, context_filemap):
	if not context or not context_filemap:
		raise ConfigurationError("No context provided, and load_context not False")

	if type(context) is not list:
		context = [context]

	js = {'@context': {}}
	for ct in context:
		fn = context_filemap.get(ct, "")
		if fn:
			try:
				fh = open(fn)
				data = fh.read()
				fh.close()
			except IOError:
				raise ConfigurationError("Provided context file does not exist")
		else:
			# XXX Fetch from web
			data = "{}"

		try:
			ctx = json.loads(data)
			js['@context'].update(ctx['@context'])
		except:
			raise ConfigurationError("Provided context does not have valid JSON")				
	# this is the merged context information, not any single one
	self.context_json = js
	self.process_context()

def __init__(self, ident=None, label="", value="", content="", **kw):
	"""Initialize BaseObject."""
	super(BaseResource, self).__init__(ident)

	if self._factory.validate_profile and hasattr(self, '_okayToUse'): 
		if not self._okayToUse:
			raise ProfileError("Class '%s' is configured to not be used" % self.__class__._type)
		elif self._okayToUse == 2:
			self._factory.maybe_warn("Class '%s' is configured to warn on use" % self.__class__._type)

	# Set label and value/content
	if label:
		self._label = label
	# this might raise an exception if value is not allowed on the object
	# but easier to do it in the main init than on many generated subclasses

	is_sym = isinstance(self, SymbolicObject)
	is_dim = isinstance(self, Dimension)

	if value and is_dim:
		self.value = value
	elif content and is_sym:
		self.content = content
	elif value and is_sym:
		self.content = value # not the right param, but not ambiguous
	elif content and is_dim:
		self.value = content # ditto
	elif value or content: 
		raise ProfileError("Class '%s' does not hold values" % self.__class__._type)
	# Custom post initialization function for autoconstructed classes
	self._post_init(**kw)

def __init__(self, ident=None):
	self._factory = factory
	if ident is not None:
		if self._factory._is_uri(ident):
			self.id = ident
		elif ident.startswith('http'):
			# Try to find prefixable term
			hashed = ident.rsplit('#', 1)
			if len(hashed) == 1:
				(pref, rest) = ident.rsplit('/', 1)
				pref += "/"
			else:
				(pref, rest) = hashed
				pref += "#"

			if pref in self._factory.prefixes_rev:
				self._full_id = ident
				ident = "%s:%s" % (self._factory.prefixes_rev[pref], rest)

			self.id = ident
		elif ident == "":
			# Allow explicit setting of empty string
			self.id = ""
		else:
			# Allow for prefixed term that isn't ambiguously a URI
			curied = ident.split(':', 1)
			if len(curied) == 2 and curied[0] in self._factory.prefixes:
				self.id = ident
				self._full_id = self._factory.prefixes[curied[0]] + curied[1]	
			else:
				self.id = factory.base_url + self.__class__._uri_segment + "/" + ident
	elif factory.auto_assign_id:
		self.id = factory.generate_id(self)
	else:
		# Not auto assigning, and not submitted = blank node
		self.id = ""

def process_context(self):
	# Filter context looking for prefixes
	# And make reverse mapping
	# Note that this does not process scoped contexts for member_of / part_of
	for (k,v) in self.context_json['@context'].items():
		if type(v) in STR_TYPES and v[-1] in ['/', '#']:
			self.prefixes[k] = v
			self.prefixes_rev[v] = k
		elif k == "@version":
			continue
		else:
			if type(v) in STR_TYPES:
				rdf = v
			else:
				rdf = v['@id']
			self.context_rev[rdf] = k

def __setattr__(self, which, value):
	"""Attribute setting magic for error checking and resource/literal handling."""

	if which[0] == "_" or not value:
		# _label goes through here, but it would below anyway, as it takes a Literal
		object.__setattr__(self, which, value)			
	else:
		# Allow per-class setters
		if hasattr(self, 'set_%s' % which):
			fn = getattr(self, 'set_%s' % which)
			return fn(value)

		if self._factory.validate_properties or self._factory.validate_profile or self._factory.validate_range:
			ok = self._check_prop(which, value)
		elif isinstance(value, ExternalResource):
			ok = 2
		else:
			ok = 1

		if ok == 2:
			self._set_magic_resource(which, value)
		else:			
			object.__setattr__(self, which, value)

def _is_uri(self, what):
	uri_schemes = ['urn:uuid:', 'tag:', 'data:', 'mailto:', 'info:', 'ftp:/', 'sftp:/'] 
	for u in uri_schemes:
		if what.startswith(u):
			return True
	return False

def post_init(self, **kw):
	if self.__class__._classification:
		for t in self._classification:
			self.classified_as = t

@property
def type(self):
	for c in self._classhier:
		if c._type:
			return c.__name__

@type.setter
def type(self, value):
	raise AttributeError("Must not set 'type' on resources directly")

def default(self, o):
	if isinstance(o, BaseResource):
		# print("Saw %r" % o)
		return o._minToJSON()
	else:
		return JSONEncoder.default(self, o)

def __getstate__(self):
	# Make a copy of current object state
	d = self.__dict__.copy()
	# try to flush the stream
	try:
		self.log_stream.flush()
	except:
		# stream instance may not support flush()
		pass
	# Now reify the log stream
	strm = d['log_stream']
	if strm is sys.stdout:
		d['log_stream'] = ("sys.stdout", "stream")
	elif strm is sys.stderr:
		d['log_stream'] = ("sys.stderr", "stream")
	elif isinstance(strm, FILE_STREAM_CLASS):
		d['log_stream'] = (strm.name, "file")
	else:
		d['log_stream'] = None
	return d

def __setstate__(self, state):
	# State is __dict__ with a reified log_stream as above
	self.__dict__.update(state)
	if self.log_stream:
		if self.log_stream[1] == "stream":
			if self.log_stream[0] == "sys.stdout":
				self.log_stream = sys.stdout
			elif self.log_stream[0] == "sys.stderr":
				self.log_stream = sys.stderr
		elif self.log_stream[1] == "file":
			try:
				self.log_stream = open(self.log_stream[0], 'a') 
			except:
				self.log_stream = None

def set_debug_stream(self, strm):
	"""Set debug level."""
	self.log_stream = strm

def set_debug(self, typ):
	"""Set behavior on errors and warnings.

	error = squash warnings
	warn = display warnings
	error_on_warning = raise exception for a warning rather than continuing
	"""
	if typ in ['error', 'warn', 'error_on_warning']:
		self.debug_level = typ
	else:
		raise ConfigurationError("Only levels are 'error', 'warn' and 'error_on_warning'")

def maybe_warn(self, msg):
	"""warn method that respects debug_level property."""
	if self.log_stream and self.debug_level == "warn":
		self.log_stream.write(msg + "\n")
		try:	
			self.log_stream.flush()
		except:
			pass
	elif self.debug_level == "error_on_warning":
		# We don't know the type, just raise a MetadataError
		raise MetadataError(msg)

def toJSON(self, what, done=None):
	""" Serialize what, making sure of no infinite loops """
	if not done:
		done = {}
	if self.json_serializer == "fast":
		out = what._toJSON_fast(top=what, done=done)
	else:
		out = what._toJSON(top=what, done=done)
	return out

def _buildString(self, js, compact=True, collapse=0):
	"""Build string from JSON."""
	try:
		if compact:
			out = json.dumps(js, separators=(',',':'), ensure_ascii=False)
		else:
			out = json.dumps(js, indent=self.json_indent, ensure_ascii=False)
	except:
		out = ""
		self.maybe_warn("Can't decode %r" % js)
		raise
	if collapse:
		out = self.collapse_json(out, collapse)
	return out

def toString(self, what, compact=True, collapse=0, done=None):
	"""Return JSON setialization as string."""
	if not done:
		done = {}
	js = self.toJSON(what, done=done)
	return self._buildString(js, compact, collapse)

def toHtml(self, what, done=None):
	enc = JSONEncoder(indent=self.json_indent, ensure_ascii=False)
	js = self.toJSON(what, done=done)
	res = ['<pre><span>']
	lineno = 0
	for y in enc.iterencode(js):
		# split newlines
		if '\n' in y:
			sp = y.split('\n')
			x2 = []
			for z in sp[:-1]:
				if z:
					x2.append(z)
				x2.append('\n')
			if sp[-1]:
				x2.append(sp[-1])
		else:
			x2 = [y]

		for x in x2:
			if x[0] == '"':
				s = x.strip()[1:-1]
				clss = "str"
				if s.startswith('http') or self._is_uri(s):
					x = '"<a href="%s">%s</a>"' % (s, s)
				elif s in ["@context"]:
					clss = "str context"
				res.append('<span class="%s">%s</span>' % (clss, x))
			elif x[0].isdigit():
				res.append('<span class="int">%s</span>' % x)						
			elif x[0] in [":", ","]:
				res.append('<span class="sep">%s</span>' % x)	
			elif x[0]  == "{":
				res.append('<span class="bsep">%s</span><span class="block">' % x)
			elif x[0]  == "[":
				res.append('<span class="asep">%s</span><span class="ablock">' % x)
			elif x[0] == "}":
				res.append('</span><span class="bsep">%s</span>' % x)
			elif x[0] == "]":
				res.append('</span><span class="asep">%s</span>' % x)
			elif x == '\n':
				res.append('\n<span class="line" data-lno="%s"></span>' % lineno)
				lineno += 1
			elif x.isspace():
				res.append(x)
			else:
				print("*** Unhandled: %r" % x)
				res.append(x)
	res.append('</span></pre>')
	return ''.join(res)

def toFile(self, what, compact=True, filename="", done=None):
	"""Write to local file.

	Creates directories as necessary
	"""

	if not done:
		done = {}
	js = self.toJSON(what, done=done)

	if not filename:
		myid = js['id']
		mdb = self.base_url
		if not myid.startswith(mdb):
			raise ConfigurationError("The id of that object is not the base URI in the Factory")
		mdd = self.base_dir
		if not mdd:
			raise ConfigurationError("Directory on Factory must be set to write to file")
		fp = myid[len(mdb):]	
		bits = fp.split('/')
		if len(bits) > 1:
			mydir = os.path.join(mdd, '/'.join(bits[:-1]))		
			try:
				os.makedirs(mydir)
			except OSError:
				pass
		if self.filename_extension:
			fp = fp + self.filename_extension
		filename = os.path.join(mdd, fp)

	fh = open(filename, 'w')
	out = self._buildString(js, compact)
	fh.write(out)
	fh.close()
	return out

def _toJSON(self, done, top=None):
	if self._factory.elasticsearch_compatible:
		return {'id': self.id}
	else:
		return self.id

def __dir__(self):
	d = dir(self.__class__)
	d.extend(self.list_all_props())
	return sorted(d)

def __eq__(a, b):
	if id(a) == id(b):
		return True
	if not a or not b:
		return False
	if not isinstance(b, BaseResource) or not isinstance(a, BaseResource):
		return False
	ap = a.list_my_props()
	bp = b.list_my_props()
	if ap != bp:
		return False
	for p in ap:
		av = getattr(a, p)
		bv = getattr(b, p)
		if av != bv:
			return False
	return True

def _post_init(self, **kw):
	# Expect this to be overridden / replaced
	pass

def _check_reference(self, data):
	"""True if data is a resource or reference to a resource"""
	# "http://..."
	# {"@id": "http://..."}
	# or list of above
	if type(data) in STR_TYPES:
		return data.startswith('http')
	elif type(data) is dict:
		return 'id' in data
	elif isinstance(data, BaseResource):
		return True
	elif type(data) is list:
		for d in data:
			if type(d) in STR_TYPES and not d.startswith('http'):
				return False
			elif type(d) is dict and not 'id' in d:
				return False
		return True
	else:
		self._factory.maybe_warn("expecing a resource, got: %r" % (data))
		return True

def list_all_props_with_range(self, filter=None, okay=None):
	props = {}
	for c in self._classhier:		
		for k,v in c._all_properties.items():
			if not k in props and \
				(not okay or (okay and v.profile_okay)) and \
				(filter is None or isinstance(filter, v.range) or \
					filter is v.range):
				props[k] = v.range
	return props

def list_my_props(self, filter=None):
	d = self.__dict__.copy()		
	props = []
	for (k,v) in d.items():
		if k[0] != "_" or k in self._factory.underscore_properties:
			# real property
			if filter:
				if isinstance(v, filter):
					props.append(k)
				elif isinstance(v, list):
					for i in v:
						if isinstance(i, filter):
							props.append(k)
							break
			else:
				props.append(k)		
	return props

def allows_multiple(self, propName):
	""" Does propName allow multiple values on this class """
	for c in self._classhier:
		if propName in c._all_properties:
			v = c._all_properties[propName]
			return bool(v.multiple_okay)
	raise DataError("Cannot set '%s' on '%s'" % (propName, self.__class__.__name__))

def clone(self, minimal=False):
	""" Make a shallow copy of self. If minimal flag is set, only return id, type and _label """
	new = self.__class__(ident=self.id)
	if minimal:
		if self._label:
			new._label = self._label
	else:
		for p in self.list_my_props():
			curr = getattr(self, p)
			if type(curr) == list:
				for v in curr:
					setattr(new, p, v)
			else:
				setattr(new, p, curr)
	return new

def register_aat_class(name, data):
	data['vocab'] = 'aat'
	register_vocab_class(name, data)

def add_classification(obj, cl_type):
	c = cl_type()
	for cn in c._classification:
		if hasattr(obj, 'classified_as') and not cn in obj.classified_as:
			obj.classified_as = cn
		elif not hasattr(obj, 'classified_as'):
			obj.classified_as = cn
	return obj

def make_multitype_obj(*args, **kw):
	# (class1, class2, class3, name=foo, other=bar)
	inst = args[0](**kw)
	for c in args[1:]:
		for cn in c._classification:
			if hasattr(inst, 'classified_as') and not cn in inst.classified_as:
				inst.classified_as = cn
			elif not hasattr(inst, 'classified_as'):
				inst.classified_as = cn
	return inst

def conceptual_only_parts():
	# Make .part work as expected for Right
	# which is only propositional and not symbolic, so P148 not P106

	def set_c_part(self, value):
		self.c_part = value
	def set_c_part_of(self, value):
		self.c_part_of = value

	def rights_getter(self, what):
		if what == "part":
			return self.c_part
		elif what == "part_of":
			return self.c_part_of
		else:
			object.__getattr__(self, what)

	Right.set_part = set_c_part
	Right.set_part_of = set_c_part_of
	Right._property_name_map['c_part'] = 'part'
	Right._property_name_map['c_part_of'] = 'part_of'
	Right._all_properties['part'] = PropositionalObject._all_properties['c_part']
	Right._all_properties['part_of'] = PropositionalObject._all_properties['c_part_of']
	Right.__getattr__ = rights_getter

def add_art_setter():
	# Linked.Art profile requires aat:300133025 on all artworks
	# Art can be a HumanMadeObject or an InformationObject
	# set it by adding art=1 to the constructor

	def art_post_init(self, **kw):
		super(HumanMadeObject, self)._post_init(**kw)
		if "art" in kw:
			self.classified_as = instances['artwork']
	HumanMadeObject._post_init = art_post_init

	def art2_post_init(self, **kw):
		if "art" in kw:
			self.classified_as = instances['artwork']
		super(InformationObject, self)._post_init(**kw)
	InformationObject._post_init = art2_post_init

def lint_lines(self, identifier, lines):
    self._reporter.start_file(identifier)
    self._parameters.start_new_file(identifier, lines)

    for _ in self._parameters:
        self._run_checkers(RULES["common"])

        if self._parameters.is_code:
            self._run_checkers(RULES["code"])

        if self._parameters.is_comment:
            self._run_checkers(RULES["comment"])

    self._reporter.finalize_file()

    return (self._parameters.lines, self._reporter)

@property
def line_number(self):
    return self._next - 1

def lint(self, line, filename, code_line, indent_size):
    if self._filename != filename:
        self._start_new_file(filename)

    if self._reset_supress_indent:
        self._reset_supress_indent = False
        self._suppress_indent = False

    if self._suppress_indent:
        self._analyse_inline_form(line)
    elif self._is_inline_form(line):
        self._suppress_indent = True
    else:
        self._analyse_indentation(code_line)

    stripped_line = line.lstrip()

    if not stripped_line:
        return

    indent = len(line) - len(stripped_line)

    if self._suppress_indent:
        indent_wanted = 0
    else:
        indent_wanted = self._indent_level * indent_size

    if indent != indent_wanted:
        if self._suppress_indent:
            yield (Category.WARNING,
                   indent,
                   "bad-indented-inline-form",
                   (f"wrong indentation (found {indent} spaces, "
                    f"exptected {indent_wanted})"))
        else:
            yield (Category.WARNING,
                   indent,
                   "bad-indentation",
                   (f"wrong indentation (found {indent} spaces, "
                    f"exptected {indent_wanted})"))

@classmethod
def __register_rule(cls, rule):
    params = get_parameters(rule.lint)

    if len(params) <= 1:
        return rule

    if params[1] == "line" and rule not in RULES["common"]:
        RULES["common"].append(rule())
    elif params[1] == "code_line" and rule not in RULES["code"]:
        RULES["code"].append(rule())
    elif params[1] == "comment_line" and rule not in RULES["comment"]:
        RULES["comment"].append(rule())

    return rule

def __init__(self, cli_args=None, config=None):
    if cli_args:
        self.cli_args = cli_args
    else:
        self.cli_args = _parse_args()

    if self.cli_args.generate_config:
        _create_configuration()

    if config:
        self.config = config
    else:
        self.config = _load_configuration(self.cli_args.config)

    self.extensions = (".src", ".dat", ".sub")

    self._parameters = Parameters(self.config)
    self._reporter = self.config.REPORTER()

def _check_result(self, results, checker):
    if results is None:
        return

    for result in results:
        _, _, code, _ = result
        if code in self.config.DISABLE:
            continue

        self._reporter.report(self._build_message(result))

        if self.cli_args.fix:
            self._fix_line(checker)

def __init__(self, config):
    self._lines = []
    self._next = 0
    self._filename = None

    for attr, value in config.__dict__.items():
        if not attr.startswith("_"):
            setattr(self, attr.lower(), value)

def finalize_file(self):
    if self.messages:
        self.handle_new_file()

        for message in self.messages:
            handle = getattr(
                self, "handle_" + message.category.name.lower())
            handle(message)

    self.filename = None

def _run_method(self, method):
    parameters = []
    for parameter in get_parameters(method):
        if parameter == "self":
            continue
        parameters.append(getattr(self._parameters, parameter))

    return method(*parameters)

def __call__(self, parser, namespace, values, option_string=None):
    if namespace.generate_config and not values:
        setattr(self, self.dest, [])
        namespace.target = []
    elif values:
        setattr(self, self.dest, values)
        namespace.target = values
    else:
        parser.error(
            f"the following arguments are required: {self.dest}")

def __next__(self):
    if self._next == self.total_lines:
        raise StopIteration

    self._next += 1
    return self.lines[self.line_number]

def _analyse_indentation(self, code_line):
    if self._indent_next_line:
        self._increase_indent_level()

    if self._is_unindentation_needed(code_line):
        self._decrease_indent_level()

    if self._is_indentation_needed(code_line):
        self._indent_next_line = True

def __init__(self):
    self.filename = None
    self.messages = []
    self.found_issues = {
        Category.CONVENTION: 0,
        Category.REFACTOR: 0,
        Category.WARNING: 0,
        Category.ERROR: 0,
        Category.FATAL: 0
    }

def lint(self, code_line):
    for match in self.pattern.finditer(code_line):
        if not str(match.group(1)).isupper():
            yield match.start()

def _run_checkers(self, rules):
    for rule in rules:
        self._check_result(self._run_check(rule), rule)

def _build_message(self, result):
    category, column, code, message = result
    return Message(
        category, code, self._parameters.line_number, column, message)

@property
def filename(self):
    return self._filename

@property
def lines(self):
    return self._lines

@property
def total_lines(self):
    return len(self._lines)

@property
def line(self):
    return (self.lines[self.line_number]
            if self.line_number < self.total_lines
            else None)

@property
def code_line(self):
    return self.line.split(";", 1)[0]

@property
def is_code(self):
    return (not self.line.lstrip().startswith(";") and
            not self.line.lstrip().startswith("&"))

@property
def is_comment(self):
    return any(char in self.line for char in [";", "&"])

def start_file(self, filename):
    self.filename = filename
    self.messages = []

def report(self, message):
    self.found_issues[message.category] += 1
    self.messages.append(message)

@staticmethod
def _is_indentation_needed(code_line):
    return not IndentationChecker.INDENT_PATTERN.search(code_line) is None

@staticmethod
def _is_unindentation_needed(code_line):
    return not IndentationChecker.UNINDENT_PATTERN.search(code_line) is None

@staticmethod
def _is_inline_form(code_line):
    return not IndentationChecker.ILF_PATTERN.search(code_line) is None

@property
def pattern(self):
    return re.compile(r"(?<!#)(\b(?:" + "|".join(KEYWORDS) + r")\b)",
                      re.IGNORECASE)

def lint(self, code_line):
    for column in super().lint(code_line):
        yield (Category.WARNING,
               column,
               "wrong-case-keyword",
               "lower or mixed case keyword")

@property
def pattern(self):
    return re.compile(r"(?<!#)(\b(?:" + "|".join(BUILT_IN_TYPES) + r")\b)",
                      re.IGNORECASE)

@line.setter
def line(self, value):
    self.lines[self.line_number] = value

@property
def comment_line(self):
    if len(self.line.split(";")) == 2:
        return self.line.split(";", 1)[1]

    if (self.line.split("&")) == 2:
        return self.line.split("&", 1)[1]

    return ""

