@classmethod
def _colorize(cls, message, style):
    return cls._get_ansi_code(*style) + message + cls.RESET

@classmethod
def _get_ansi_code(cls, foreground=None, styles=None):
    code = []

    if foreground:
        code.append(cls.COLORS[foreground])
    if styles:
        for style in styles:
            code.append(cls.STYLES[style])

    if code:
        return cls.PREFIX + ";".join(code) + cls.END
    return ""

def lint(self, code_line):
    for match in self.WHITESPACE_PATTERN.finditer(code_line.strip()):
        yield (Category.CONVENTION,
               match.start(),
               "superfluous-whitespace",
               "superfluous whitespace")

@abstractproperty
def pattern(self):
    raise NotImplementedError

def fix(self, code_line, comment_line):
    return (self.pattern.sub(self._fix_match, code_line) +
            ((";" + comment_line) if comment_line else ""))

def lint(self, code_line):
    for column in super().lint(code_line):
        yield  (Category.WARNING,
                column,
                "wrong-case-type",
                "lower or mixed case built-in type")

def get_parameters(method):
    return [parameter.name
            for parameter in inspect.signature(method).parameters.values()
            if parameter.kind == parameter.POSITIONAL_OR_KEYWORD]

def lint(self):
    for target in self.cli_args.target:
        target = os.path.expanduser(target)
        if os.path.isdir(target):
            self.lint_directory(target)
        else:
            self.lint_file(target)

        self._reporter.finalize()

def lint_directory(self, dirname):
    for dirpath, _, filenames in os.walk(dirname):
        for filename in sorted(filter(
                lambda file: file.endswith(self.extensions), filenames)):
            self.lint_file(os.path.join(dirpath, filename))

def _fix_file(self, filename):
    with open(filename, "w") as content:
        content.writelines(self._parameters.lines)

def _create_configuration():
    from shutil import copyfile

    source = os.path.join(os.path.dirname(__file__), DEFAULT_CONFIG_NAME)
    destination = f"./krllint.{DEFAULT_CONFIG_NAME}"

    if os.path.exists(destination):
        raise Exception(f"Configuration file already exists ({destination})!")

    try:
        copyfile(source, destination)
    except:
        raise Exception("Configuration file could not be created!")

def fix(self, line, indent_char, indent_size):
    invalid_character = [" ", "\t"]
    invalid_character.remove(indent_char)
    return line.replace(invalid_character[0], indent_char * indent_size)

def fix(self, code_line, comment_line):
    return (self.WHITESPACE_PATTERN.sub(lambda _: " ", code_line) +
            ((";" + comment_line) if comment_line else ""))

