def lint_lines(self, identifier, lines):
    self._reporter.start_file(identifier)
    self._parameters.start_new_file(identifier, lines)

    for _ in self._parameters:
        self._run_checkers(RULES["common"])

        if self._parameters.is_code:
            self._run_checkers(RULES["code"])

        if self._parameters.is_comment:
            self._run_checkers(RULES["comment"])

    self._reporter.finalize_file()

    return (self._parameters.lines, self._reporter)

@property
def line_number(self):
    return self._next - 1

def lint(self, line, filename, code_line, indent_size):
    if self._filename != filename:
        self._start_new_file(filename)

    if self._reset_supress_indent:
        self._reset_supress_indent = False
        self._suppress_indent = False

    if self._suppress_indent:
        self._analyse_inline_form(line)
    elif self._is_inline_form(line):
        self._suppress_indent = True
    else:
        self._analyse_indentation(code_line)

    stripped_line = line.lstrip()

    if not stripped_line:
        return

    indent = len(line) - len(stripped_line)

    if self._suppress_indent:
        indent_wanted = 0
    else:
        indent_wanted = self._indent_level * indent_size

    if indent != indent_wanted:
        if self._suppress_indent:
            yield (Category.WARNING,
                   indent,
                   "bad-indented-inline-form",
                   (f"wrong indentation (found {indent} spaces, "
                    f"exptected {indent_wanted})"))
        else:
            yield (Category.WARNING,
                   indent,
                   "bad-indentation",
                   (f"wrong indentation (found {indent} spaces, "
                    f"exptected {indent_wanted})"))

@classmethod
def __register_rule(cls, rule):
    params = get_parameters(rule.lint)

    if len(params) <= 1:
        return rule

    if params[1] == "line" and rule not in RULES["common"]:
        RULES["common"].append(rule())
    elif params[1] == "code_line" and rule not in RULES["code"]:
        RULES["code"].append(rule())
    elif params[1] == "comment_line" and rule not in RULES["comment"]:
        RULES["comment"].append(rule())

    return rule

def __init__(self, cli_args=None, config=None):
    if cli_args:
        self.cli_args = cli_args
    else:
        self.cli_args = _parse_args()

    if self.cli_args.generate_config:
        _create_configuration()

    if config:
        self.config = config
    else:
        self.config = _load_configuration(self.cli_args.config)

    self.extensions = (".src", ".dat", ".sub")

    self._parameters = Parameters(self.config)
    self._reporter = self.config.REPORTER()

def _check_result(self, results, checker):
    if results is None:
        return

    for result in results:
        _, _, code, _ = result
        if code in self.config.DISABLE:
            continue

        self._reporter.report(self._build_message(result))

        if self.cli_args.fix:
            self._fix_line(checker)

def __init__(self, config):
    self._lines = []
    self._next = 0
    self._filename = None

    for attr, value in config.__dict__.items():
        if not attr.startswith("_"):
            setattr(self, attr.lower(), value)

def finalize_file(self):
    if self.messages:
        self.handle_new_file()

        for message in self.messages:
            handle = getattr(
                self, "handle_" + message.category.name.lower())
            handle(message)

    self.filename = None

def _run_method(self, method):
    parameters = []
    for parameter in get_parameters(method):
        if parameter == "self":
            continue
        parameters.append(getattr(self._parameters, parameter))

    return method(*parameters)

def __call__(self, parser, namespace, values, option_string=None):
    if namespace.generate_config and not values:
        setattr(self, self.dest, [])
        namespace.target = []
    elif values:
        setattr(self, self.dest, values)
        namespace.target = values
    else:
        parser.error(
            f"the following arguments are required: {self.dest}")

def __next__(self):
    if self._next == self.total_lines:
        raise StopIteration

    self._next += 1
    return self.lines[self.line_number]

def _analyse_indentation(self, code_line):
    if self._indent_next_line:
        self._increase_indent_level()

    if self._is_unindentation_needed(code_line):
        self._decrease_indent_level()

    if self._is_indentation_needed(code_line):
        self._indent_next_line = True

def __init__(self):
    self.filename = None
    self.messages = []
    self.found_issues = {
        Category.CONVENTION: 0,
        Category.REFACTOR: 0,
        Category.WARNING: 0,
        Category.ERROR: 0,
        Category.FATAL: 0
    }

def lint(self, code_line):
    for match in self.pattern.finditer(code_line):
        if not str(match.group(1)).isupper():
            yield match.start()

def _run_checkers(self, rules):
    for rule in rules:
        self._check_result(self._run_check(rule), rule)

def _build_message(self, result):
    category, column, code, message = result
    return Message(
        category, code, self._parameters.line_number, column, message)

