def __eq__(a, b):
	if id(a) == id(b):
		return True
	if not a or not b:
		return False
	if not isinstance(b, BaseResource) or not isinstance(a, BaseResource):
		return False
	ap = a.list_my_props()
	bp = b.list_my_props()
	if ap != bp:
		return False
	for p in ap:
		av = getattr(a, p)
		bv = getattr(b, p)
		if av != bv:
			return False
	return True

