            if not os.path.isabs(template_path):
                template_path = os.path.abspath(template_path)

            self.template_path = template_path

        path = args[0]
        if not os.path.isabs(args[0]):
            path = os.path.abspath(args[0])

        self.create_document(path)

        #: Initialize.
        self.clear()

        return func
    return __generate

def _autodoc(func, *_args, **_kwargs):
    if len(_args) > 0:
        #: Instance or class method.
        response = func(_args[0])
    else:
        #: Function.
        if len(_kwargs) > 0:
            response = func(**_kwargs)
        else:
            response = func()

    self.parse(args[0], response)

    return func

@wraps(func)
def __generate(*_args):
    if len(_args) > 0:
        arg = _args[0]
    else:
        arg = _args

    if self._is_runnable() is False:
        return func

    func(arg)

    if 'template' in kwargs:
        template_path = kwargs['template']
        if not os.path.isabs(template_path):
            template_path = os.path.abspath(template_path)

        self.template_path = template_path

    path = args[0]
    if not os.path.isabs(args[0]):
        path = os.path.abspath(args[0])

    self.create_document(path)

    #: Initialize.
    self.clear()

    return func

def to_unicode(x, charset=sys.getdefaultencoding(), errors='strict',
               allow_none_charset=False):
    if x is None:
        return None
    if not isinstance(x, bytes):
        return text_type(x)
    if charset is None and allow_none_charset:
        return x
    return x.decode(charset, errors)

