def _define_numerical_dict(the_dict):
    # Check that the entered dictionary is indeed a dictionary of integers and floats
    # Can take None as value
    if not the_dict:
        the_dict = the_dict
    elif isinstance(the_dict, dict):
        if not all([isinstance(x, (float, int)) for x in the_dict.values()]):
            raise ValueError('All values in the dictionary must be integer or float')
    else:
        raise TypeError('The parameter can only take a dictionary or None')
    return the_dict

def __init__(self, arbitrary_number=999, variables=None, imputer_dict=None):

    if isinstance(arbitrary_number, int) or isinstance(arbitrary_number, float):
        self.arbitrary_number = arbitrary_number
    else:
        raise ValueError('arbitrary_number must be numeric of type int or float')

    self.variables = _define_variables(variables)

    self.imputer_dict = _define_numerical_dict(imputer_dict)

def _find_numerical_variables(X, variables=None):
    # Find numerical variables in a data set or check that
    # the variables entered by the user are numerical.
    if not variables:
        variables = list(X.select_dtypes(include='number').columns)
        if len(variables) == 0:
            raise ValueError('No numerical variables in this dataframe. Please check variable format with dtypes')
    else:
        if len(X[variables].select_dtypes(exclude='number').columns) != 0:
            raise TypeError("Some of the variables are not numerical. Please cast them as numerical "
                            "before calling this transformer")
    return variables

def _find_categorical_variables(X, variables=None):
    # Find categorical variables in a data set or check that
    # the variables entered by user are categorical.
    if not variables:
        variables = list(X.select_dtypes(include='O').columns)
        if len(variables) == 0:
            raise ValueError('No categorical variables in this dataframe. Please check variable format with dtypes')
    else:
        # variables indicated by user
        if len(X[variables].select_dtypes(exclude='O').columns) != 0:
            raise TypeError("Some of the variables are not categorical. Please cast them as object "
                            "before calling this transformer")
    return variables

def _define_variables(variables):
    # Check that variable names are passed in a list.
    # Can take None as value
    if not variables or isinstance(variables, list):
        variables = variables
    else:
        variables = [variables]
    return variables

def _is_dataframe(X):
    # checks if the input is a dataframe. Also creates a copy,
    # important not to transform the original dataset.
    if not isinstance(X, pd.DataFrame):
        raise TypeError("The data set should be a pandas dataframe")
    return X.copy()

def _check_contains_na(X, variables):
    if X[variables].isnull().values.any():
        raise ValueError('Some of the variables to trasnform contain missing values. Check and remove those '
                         'before using this transformer.')

def _define_seed(X, index, seed_variables, how='add'):
    # determine seed by adding or multiplying the value of 1 or
    # more variables
    if how == 'add':
        internal_seed = int(np.round(X.loc[index, seed_variables].sum(), 0))
    elif how == 'multiply':
        internal_seed = int(np.round(X.loc[index, seed_variables].product(), 0))
    return internal_seed

def __init__(self, imputation_method='median', variables=None):

    if imputation_method not in ['median', 'mean']:
        raise ValueError("imputation_method takes only values 'median' or 'mean'")

    self.imputation_method = imputation_method
    self.variables = _define_variables(variables)

def __init__(self, distribution='gaussian', tail='right', fold=3, variables=None):

    if distribution not in ['gaussian', 'skewed', 'max']:
        raise ValueError("distribution takes only values 'gaussian', 'skewed' or 'max'")

    if tail not in ['right', 'left']:
        raise ValueError("tail takes only values 'right' or 'left'")

    if fold <= 0:
        raise ValueError("fold takes only positive numbers")

    self.distribution = distribution
    self.tail = tail
    self.fold = fold
    self.variables = _define_variables(variables)

def __init__(self, variables=None, random_state=None, seed='general', seeding_method='add'):

    if seed not in ['general', 'observation']:
        raise ValueError("seed takes only values 'general' or 'observation'")

    if seeding_method not in ['add', 'multiply']:
        raise ValueError("seeding_method takes only values 'add' or 'multiply'")

    if seed == 'general' and random_state:
        if not isinstance(random_state, int):
            raise ValueError("if seed == 'general' the random state must take an integer")

    if seed == 'observation' and not random_state:
        raise ValueError("if seed == 'observation' the random state must take the name of one or more variables "
                         "which will be used to seed the imputer")

    self.variables = _define_variables(variables)
    self.random_state = random_state
    self.seed = seed
    self.seeding_method = seeding_method

def __init__(self, how='missing_only', variables=None):

    if how not in ['missing_only', 'all']:
        raise ValueError("how takes only values 'missing_only' or 'all'")

    self.variables = _define_variables(variables)
    self.how = how

def _find_all_variables(X, variables=None):
    # Find all variables in a data set
    if not variables:
        variables = list(X.columns)
    else:
        # variables indicated by user
        if len(set(variables).difference(X.columns)) != 0:
            raise TypeError("Some variables are not present in the dataset. Please check your variable"
                            " list")
    return variables

