def prefix_hash(self) -> bytes:
    try:
        return self.tx_id_le  # Prevent redundant hashing
    except AttributeError:
        return utils.blake256(self.prefix())

def prefix(self) -> bytes:
    data = DecredByteData()
    data += self.version[:2]
    data += b'\x01\x00'  # Serialization type 1 (prefix only)
    data += shared.VarInt(len(self.tx_ins))
    for tx_in in self.tx_ins:
        data += tx_in
    data += shared.VarInt(len(self.tx_outs))
    for tx_out in self.tx_outs:
        data += tx_out
    data += self.lock_time
    data += self.expiry
    return data.to_bytes()

def witness(self) -> bytes:
    data = DecredByteData()
    data += self.version[:2]
    data += b'\x02\x00'  # Serialization type 2 (witness only)
    data += shared.VarInt(len(self.tx_witnesses))
    for tx_witness in self.tx_witnesses:
        data += tx_witness
    return data.to_bytes()

def witness_signing(self) -> bytes:
    data = DecredByteData()
    data += self.version[:2]
    data += b'\x03\x00'  # Serialization type 3 (witness signing)
    data += shared.VarInt(len(self.tx_witnesses))
    for tx_witness in self.tx_witnesses:
        data += shared.VarInt(tx_witness.script_len)
        data += tx_witness.script_sig
    return data.to_bytes()

def _hash_prevouts(self, anyone_can_pay: bool) -> bytes:
    if anyone_can_pay:
        return b'\x00' * 32

    data = z.ZcashByteData()
    for tx_in in self.tx_ins:
        data += tx_in.outpoint

    return utils.blake2b(
        data=data.to_bytes(),
        digest_size=32,
        person=b'ZcashPrevoutHash')

def _hash_sequence(self, sighash_type: int, anyone_can_pay: bool) -> bytes:
    if anyone_can_pay or sighash_type == shared.SIGHASH_SINGLE:
        return b'\x00' * 32

    data = z.ZcashByteData()
    for tx_in in self.tx_ins:
        data += tx_in.sequence

    return utils.blake2b(
        data=data.to_bytes(),
        digest_size=32,
        person=b'ZcashSequencHash')

def _hash_outputs(self, sighash_type: int, index: int) -> bytes:
    if sighash_type not in [shared.SIGHASH_ALL, shared.SIGHASH_SINGLE]:
        return b'\x00' * 32

    data = z.ZcashByteData()

    if sighash_type == shared.SIGHASH_ALL:
        for tx_out in self.tx_outs:
            data += tx_out

    if sighash_type == shared.SIGHASH_SINGLE:
        if index > len(self.tx_outs):
