def call_clapi(self, action=None, obj=None, values=None):
    """
    Call an endpoint of Centreon Web for clapi wrapper

    :param action: The clapi action
    :type action: String
    :param obj: The clapi object
    :type obj: String
    :param values: The values for the call
    :type values: mixed
    :return: The response of call
    :rtype: dict
    """
    if self.auth_token is None:
        self.auth()

    data = {}

    if action is not None:
        data['action'] = action
    if obj is not None:
        data['object'] = obj
    if values is not None:
        data['values'] = values

    request = requests.post(
        self.url + '/api/index.php?action=action&object=centreon_clapi',
        headers={
            'Content-Type': 'application/json',
            'centreon-auth-token': self.auth_token
        },
        data=json.dumps(data),
        verify=self.check_ssl
    )
    try:
        request.raise_for_status()
        return True, request.json()
    except requests.HTTPError as e:
        return False, json.dumps(['error',
                                  {'message': str(e)},
                                  {'code': str(e.response.status_code),
                                   'reason': str(e.response.reason),
                                   'text': e.response.text}])

def build_param(param=None, objecttype=None, attr='name'):
    if param is None:
        return param
    #    raise ("Param must be defined")
    param_list = list()
    return_list = list()
    if not isinstance(param, list):
        param_list.append(param)
    else:
        param_list = list(param)
    for k in param_list:
        if isinstance(k, str):
            return_list.append(k)
        elif isinstance(k, objecttype):
            return_list.append(k.__dict__[attr])
    return return_list

@staticmethod
def post_refresh(func):
    """
    Decorator that call __refresh_list() after func unless
    function's call contains 'post_refresh=False'
    eg:
        @post_refresh
        def hello(w, post_refresh=False):
            ...
    """
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        # args[0] is always self
        # https://coderwall.com/p/jo39na/python-decorators-using-self
        if kwargs.get("post_refresh", True):
            args[0]._refresh_list()
        return result
    return wrapper

@staticmethod
def pre_refresh(func):
    def wrapper(*args, **kwargs):
        args[0]._refresh_list()
        return func(*args, **kwargs)
    return wrapper

