def __init__(self, number: int, length: Optional[int] = None):
    super().__init__()
    if number < 0x0:
        raise ValueError('VarInt cannot be less than 0. '
                         'Got: {}'.format(number))
    if number > 0xffffffffffffffff:
        raise ValueError('VarInt cannot be greater than (2 ** 64) - 1. '
                         'Got: {}'
                         .format(number))
    if number <= 0xfc:
        pass  # No prefix
    elif number <= 0xffff or length == 3:
        self += bytes([0xfd])
        length = 3
    elif number <= 0xffffffff or length == 5:
        self += bytes([0xfe])
        length = 5
    elif number <= 0xffffffffffffffff or length == 9:
        self += bytes([0xff])
        length = 9
    self += utils.i2le(number)

    if length is not None:
        while len(self) < length:
            self += b'\x00'

    self.number = number

    self._make_immutable()

def _hash_joinsplits(self) -> bytes:
    if len(self.tx_joinsplits) == 0:
        return b'\x00' * 32

    data = z.ZcashByteData()

    for joinsplit in self.tx_joinsplits:
        data += joinsplit

    data += cast(bytes, self.joinsplit_pubkey)

    return utils.blake2b(
        data=data.to_bytes(),
        digest_size=32,
        person=b'ZcashJSplitsHash')

