def __ne__(self, other):
    '''
    ByteData, byte-like -> bool
    Define != operator.
    Compares self._bytes to other.
    '''
    if isinstance(other, bytes) or isinstance(other, bytearray):
        return self._bytes != other
    elif isinstance(other, ByteData):
        return self._bytes != other._bytes
    else:
        raise TypeError('Equality not supported for ByteData and {}.'
                        .format(type(other)))

def blake2b(data: bytes = b'', **kwargs) -> bytes:
    '''blake2b digest of a message'''
    b2 = hashlib.blake2b(**kwargs)
    b2.update(data)
    return b2.digest()

def parse(address: str) -> bytes:
    '''
    Decode an address to the underlying raw bytes

    Args:
        address: The address to parse
    Returns:
        The raw bytestring encoded by the address
    '''
    try:
        return bytearray(riemann.network.LEGACY_ENCODER.decode(address))
    except ValueError:
        pass

    try:
        return bytearray(riemann.network.SEGWIT_ENCODER.decode(address))
    except Exception:
        pass

    try:
        return bytearray(riemann.network.CASHADDR_ENCODER.decode(address))
    except Exception:
        pass

    raise ValueError(
        'Unsupported address format. Got: {}'.format(address))

