def _round_connection(self):
    self._current = (self._current + 1) % len(self._connections)
    self.host, self.port = self._connections[self._current]

def send(self, msg):
    result = ''
    current_bytes = 0
    for data in msg:
        data_size = sys.getsizeof(data, 0)
        if data_size > self._limit:
            continue
        current_bytes += data_size
        if current_bytes <= self._limit:
            result += data
        else:
            self._send_msg(result)
            current_bytes = data_size
            result = data
    if current_bytes:
        self._send_msg(result)
    self._round_connection()

@staticmethod
def force_level(*args, **kwargs):
    """
    Function that make possible to force level value for specific loggers

    :param args: (str or dict) level name or configuration for more levels
    :param kwargs: (dict) name of logger and value as elements
    """
    if len(args) > 1:
        raise TypeError("force_level() takes exactly one argument "
                        "or named arguments ({0} given)".format(len(args)))

    elif len(args) == 1:
        if isinstance(args[0], int):
            PropagationLogger._global_propagation_level = args[0]
        elif isinstance(args[0], "".__class__):
            PropagationLogger._global_propagation_level = \
                logging.getLevelName(args[0])
        elif isinstance(args[0], dict):
            PropagationLogger._forcing = args[0]
    else:
        if kwargs:
            PropagationLogger._forcing = kwargs
        else:
            raise TypeError("force_level() takes exactly one "
                            "argument or named arguments (0 given)")

def getEffectiveLevel(self):
    """
    Get the effective level for this logger.

    Loop through this logger and its parents in the logger hierarchy,
    looking for a non-zero logging level. Return the first one found.

    Accepting propagation configuration as first priority.
    """
    if self.name in PropagationLogger._forcing:
        level = PropagationLogger._forcing[self.name]
        if isinstance(level, int):
            return level
        else:
            return logging.getLevelName(level)
    if PropagationLogger._global_propagation_level != logging.NOTSET:
        return PropagationLogger._global_propagation_level
    return Logger.getEffectiveLevel(self)

@staticmethod
def _jsonify_message(index, data):
    if 'exc_info' in data and data['exc_info']:
        data.update(JsonFormatter.format_exception(data['exc_info']))
        del data['exc_info']
    try:
        message = '\n'.join([
            logging_json_encoder.encode(index),
            logging_json_encoder.encode(data),
            '',  # it's here to add \n at end of the message
        ])
    except TypeError as e:
        message = '\n'.join([
            json.dumps(index),
            json.dumps({"error": "unable to serialize"}),
            '',
        ])
        warnings.warn('cannot serialize: {0}'.format(e))
    except UnicodeDecodeError as e:  # pragma: no cover
        message = '\n'.join([
            json.dumps(index),
            json.dumps({"error": "unable to decode"}),
            '',
        ])
        warnings.warn('cannot decode as utf8: {0}'.format(e))
    return message

@staticmethod
def _count_to_remove_chars(over_limit, msg):  # pragma: no cover
    to_remove_chars_count = 0
    if sys.version_info[0] == 3:
        # size of one character in string class in python 3.x is 2
        to_remove_chars_count = int(math.ceil(over_limit / 2))
    else:
        if isinstance(msg, unicode):
            # size of one character in unicode class in python 2.x is 4
            to_remove_chars_count = int(math.ceil(over_limit / 4))
        elif isinstance(msg, str):
            # size of one character in str in python 2.x in 1
            to_remove_chars_count = over_limit
    return int(math.fabs(to_remove_chars_count))

@staticmethod
def _truncate_too_long_message(index, data, size, limit):
    # is added to result when we have data over limit
    over_limit = (size - limit) + MTL_OVER_SIZE
    to_remove_chars_count = JsonFormatter._count_to_remove_chars(
        over_limit, data['message'])
    data['message'] = data['message'][:-to_remove_chars_count]
    data['ES_MTL'] = True
    return JsonFormatter._jsonify_message(index, data)

