def set_format(self, formatstring, logger_name=None, top_level=True, datefmt=None):
    logger_name = logger_name or self.current_logger_name()
    if top_level:
        logger_name = logger_name.split(".")[0]
    try:
        handler = self.get_handler(logger_name)
    except KeyError:
        handler = None
    if not handler:
        handler = self.add_std_handler(logger_name)
    if datefmt:
        formatter = logging.Formatter(formatstring, datefmt=datefmt)
    else:
        formatter = logging.Formatter(formatstring)
    handler.setFormatter(formatter)

def set_level(self, level, name=None):
    handler = self.get_handler(name)
    handler.setLevel(getattr(logging, level.upper()))

def get_calling_module(name=None, top_level_only=True):
    def top_module(mname):
        if top_level_only:
            return mname.split(".")[0]

        else:
            return mname

    s = inspect.stack()

    def modules_iter():
        for i in range(len(s)):
            m = inspect.getmodule(s[i][0])
            # func_name = s[i][3]
            yield m

    x = next(
        (
            m
            for m in modules_iter()
            if m and top_module(m.__name__) != top_module(__name__)
        ),
        None,
    )
    return x

def get_handler(self, name=None, top_level=True):
    name = name or self.current_logger_name()
    if top_level:
        name = name.split(".")[0]
    logger = self.get_logger(name)
    for h in logger.handlers:
        if isinstance(h, (StdHandler, logging.NullHandler)):
            return h

    raise KeyError("no logx-related handler found on this logger")

def get_nicest_module_name(m=None):
    if not m:
        m = get_calling_module()
    if m:
        _name = m.__name__
    else:
        return "__main__"

    def is_main(name):
        return name == "__main__"

    if is_main(_name):
        if m.__spec__:
            return m.__spec__.name

        else:
            return inspect.getmodulename(inspect.getfile(m))

    else:
        return _name

def emit(self, record):
    msg = self.format(record)
    if record.levelno >= logging.WARNING:
        stream = sys.stderr
    else:
        stream = sys.stdout
    stream.write(msg)
    stream.write("\n")
    self.flush()

def __getattr__(self, method, *args, **kwargs):
    if method.startswith("_"):
        raise AttributeError

    logger_name = self.current_logger_name()
    try:
        logger_name = self.get_logger_with_handler(logger_name)
    except KeyError:
        self.add_std_handler(logger_name)
    _logger = logging.getLogger(logger_name)
    return getattr(_logger, method)

def modules_iter():
    for i in range(len(s)):
        m = inspect.getmodule(s[i][0])
        # func_name = s[i][3]
        yield m

def current_logger_name(self):
    name = get_nicest_module_name()
    return name

def get_logger(self, name=None):
    name = name or self.current_logger_name()
    return logging.getLogger(name)

def top_module(mname):
    if top_level_only:
        return mname.split(".")[0]

    else:
