    name = name or self.current_logger_name()
    if top_level:
        name = name.split(".")[0]
    logger = self.get_logger(name)
    for h in logger.handlers:
        if isinstance(h, (StdHandler, logging.NullHandler)):
            return h

    raise KeyError("no logx-related handler found on this logger")

def get_nicest_module_name(m=None):
    if not m:
        m = get_calling_module()
    if m:
        _name = m.__name__
    else:
        return "__main__"

    def is_main(name):
        return name == "__main__"

    if is_main(_name):
        if m.__spec__:
            return m.__spec__.name

        else:
            return inspect.getmodulename(inspect.getfile(m))

    else:
        return _name

