def soma(x):
    try:
        return sum(x)
    except:
        m = Medida(
            (sum(list(map(lambda x: x.nominal, x))),
            sum(list(map(lambda x: x.incerteza, x)))), x[0].unidades_originais)
        return m

def torna_medida(x):
    if not isinstance(x, Medida):
        return Medida(x)
    return x

def cos(x):
    x    = torna_medida(x)
    nom  = math.cos(x.nominal)
    err  = math.sin(x.nominal)
    err *= x.incerteza
    return Medida((nom, err))

def sin(x):
    x    = torna_medida(x)
    nom  = math.sin(x.nominal)
    err  = math.cos(x.nominal)
    err *= x.incerteza
    return Medida((nom, err))

def tan(x):
    x    = torna_medida(x)
    nom  = math.tan(x.nominal)
    err  = (1.0/math.cos(x.nominal))**2
    err *= x.incerteza
    return Medida((nom, err))

def cot(x):
    x    = torna_medida(x)
    nom  = (1.0/math.tan(x.nominal))
    err  = (1.0/math.sin(x.nominal))**2
    err *= x.incerteza
    return Medida((nom, err))

def sec(x):
    x    = torna_medida(x)
    nom  = math.tan(x.nominal)
    err  = (1.0/math.cos(x.nominal))*math.tan(x.nominal)
    err *= x.incerteza
    return Medida((nom, err))

def csc(x):
    x    = torna_medida(x)
    nom  = math.tan(x.nominal)
    err  = (1.0/math.sin(x.nominal))*(1.0/math.tan(x.nominal))
    err *= x.incerteza
    return Medida((nom, err))

def arc_cos(x):
    x    = torna_medida(x)
    nom  = math.acos(x.nominal)
    err  = 1/math.sqrt(1 - x.nominal**2)
    err *= x.incerteza
    return Medida((nom, err), "rad")

def arc_sin(x):
    x    = torna_medida(x)
    nom  = math.asin(x.nominal)
    err  = 1/math.sqrt(1 - x.nominal**2)
    err *= x.incerteza
    return Medida((nom, err), "rad")

def arc_tan(x):
    x    = torna_medida(x)
    nom  = math.atan(x.nominal)
    err  = 1/math.sqrt(1 - x.nominal**2)
    err *= x.incerteza
    return Medida((nom, err), "rad")

def log(x, b):
    x    = torna_medida(x)
    nom  = math.log(x.nominal, b)
    err  = math.log(math.exp(1), b)/x.nominal
    err *= x.incerteza
    return Medida((nom, err), x.unidades_originais)

def M(*args, **kwargs):
    if len(args) > 0 and isinstance(args[0], list):
        ans = []
        for m in args[0]:
            if isinstance(m, Medida):
                ans.append(m)
            else:
                ans.append(Medida(m, **kwargs))
        return ans
    else:
        return Medida(*args, **kwargs)

def checa_dim(self, outro):
    # Aplique a regra
    if self.dimensao != outro.dimensao:
        raise ValueError("dimensões físicas incompatíveis: {} vs {} ({} vs. {})".format(dimensao_em_texto(self.dimensao), dimensao_em_texto(outro.dimensao), self, outro))

def _eh_medida(self, outro):
    if not isinstance(outro, Medida):
        raise TypeError("medidas só podem ser comparadas com outras medidas")

def _torne_medida(self, outro, converter):
    m = outro
    if not isinstance(outro, Medida):
        m = Medida(outro)
    if converter:
        return m.converta(self.unidades_originais, ignore=True)
    else:
        return m

def converta(self, unidades, ignore=False):
    if isinstance(unidades, str):
        unidades = analisa_unidades(unidades)
    m = Medida(1, unidades)
    if not ignore:
        self.checa_dim(m)
    nom, err = converte_unidades(self.nominal, self.incerteza, self.unidades_originais, unidades)
    return Medida((nom, err), unidades)

def __eq__(self, outro):
    self._eh_medida(outro)
    self.checa_dim(outro)
    return abs(self.si_nominal - outro.si_nominal) <= 2 * (self.si_incerteza + outro.si_incerteza)

def __ne__(self, outro):
    self._eh_medida(outro)
    self.checa_dim(outro)
    return abs(self.si_nominal - outro.si_nominal) > 3 * (self.si_incerteza + outro.si_incerteza)

def __floordiv__(self, outro):
    m = self.__div__(outro)
    nom = math.floor(m.nominal)
    err = abs(m.nominal-nom) + m.incerteza
    return Medida((nom, err), m.unidades_originais)

def __abs__(self):
    m = Medida((abs(self.nominal), self.incerteza), self.unidades_originais)
    return m

def __rpow__(self, outro):
    outro = float(outro)
    return Medida((
        outro**self.nominal,
        outro**self.nominal * log(outro) * self.incerteza))

def __rdiv__(self, outro):
