def media(x, incerteza="desvio padrão"):
    try:
        x = list(x)
    except:
        raise ValueError("x deve ser uma lista ou algo conversível em lista")

    acumulador = copy(x[0])
    acumulador *= 0
    for elemento in x:
        acumulador += elemento
    acumulador /= len(x)

    try:
        avg = copy(acumulador)
        avg.inicializa("0", acumulador.unidades_originais)
    except:
        incerteza = "nenhum"

    avg = copy(acumulador)
    incerteza_val = 0.0
    if incerteza == "nenhum":
        return avg
    elif incerteza == "desvio padrão":
        incerteza_val = desvio_padrao(x)
        avg.inicializa((acumulador.nominal, incerteza_val), acumulador.unidades_originais)
        return avg
    elif incerteza == "propagação":
        return avg
    else:
        raise ValueError("mecanismo de incerteza desconhecido: {}".format(incerteza))

def desvio_padrao(x):
    try:
        x = list(x)
    except:
        raise ValueError("x deve ser uma lista ou algo conversível em lista")

    avg = soma(x)/len(x)

    acumulador = 0.0
    for elemento in x:
        acumulador += (elemento.nominal - avg.nominal)**2
    acumulador /= max(len(x)-1, 1)
    acumulador = math.sqrt(acumulador)
    return acumulador

def __repr__(self):
    try:
        return "<{}:*{}:+{}:{}>".format(self.nome, self.cte_multiplicativa.nominal, self.cte_aditiva.nominal, dimensao_em_texto(self.dimensao))
    except:
        return "<{}:*?:+?:{}>".format(self.nome, dimensao_em_texto(self.dimensao))

@classmethod
def from_file(cls, fin):
	"""
	Construct the header from the file.
	"""
	detach = False
	if(not isinstance(fin, (io.StringIO, io.TextIOBase))):
		fin = io.TextIOWrapper(fin)
		detach = True

	line = fin.readline()
	while(line.isspace()):
		line = fin.readline()
	data = json.loads(line)
	if(not "__type__" in data or data["__type__"] != "header"):
		fin.seek(0)
		descriptor = {}
		for k in data.keys():
			descriptor[k] = {"type": None, "modifiers": []}
		return cls(descriptor), True
	del(data["__type__"])

	if(detach):
		fin.detach()

	return cls(data), False

def additem(self, row):
	for k, v in row.items():
		self.header.check_data(k, v)
		if("unique" in self.header.descriptor[k]["modifiers"]):
			# check if the value is unique
			values = [r[k] for r in self.rows]
			if(v in values):
				raise ValueError("Value {} is not unique: {}".format(k, v))
	self.rows.append(row)

