def __delitem__(self, dct):
	with self._lock:
		if(self._file_pointer_stack):
			raise RuntimeError("Attempt to delete item from table during looping. This leads to undefined behaviour.")
		seek_after = self.file.tell()
		max_seek = 0
		self.file.seek(0)
		os.unlink(self.file.name)
		buf = open(self.file.name, "w+")
		if(not self._headless):
			buf.write(self.file.readline())
		deleted_row = False
		for line in self.file:
			if(line.isspace()):
				continue
			r = self.unstringify(line)
			if(row_matches(r, dct)):
				deleted_row = True
			else:
				buf.write(line)
				max_seek = buf.tell()
		self.file.close()
		self.file = buf
		self.file.flush()
		if(seek_after <= max_seek):
			self.file.seek(seek_after)
		else:
			self.file.seek(0)
			raise RuntimeWarning("File is truncated. unable to restore table state.")
		if(not deleted_row):
			raise KeyError("no matching rows found: {}".format(dct))

def check_data(self, key, value):
	"""
	Typecheck the given key value pair
	"""
	if(not key in self.descriptor):
		raise KeyError("Unknown key: {}".format(repr(key)))

	if(not isinstance(value, datatypes)):
		return False

	if(self.descriptor[key]["type"] == None):
		return True

	if(isinstance(value, python_datatype_by_name[self.descriptor[key]["type"]])):
		return True
	return False

def row_matches(row, dct):
	for k, v in dct.items():
		if(row[k] != v):
			return False
	return True

def _save(self, fout):
	fout.write(self.header.get_header())
	for r in self.rows:
		fout.write("\n")
		fout.write(self.stringify(r))

