def nova_unidade_por_expoente(self, e):
    global TODAS_AS_UNIDADES

    # Veja os casos especiais
    if e == 1:
        return self
    if e == 0:
        return None
    if self.simbolo+gera_expoente(e) in TODAS_AS_UNIDADES:
        return TODAS_AS_UNIDADES[self.simbolo+gera_expoente(e)]
    if self.nome+"^"+str(e) in TODAS_AS_UNIDADES:
        return TODAS_AS_UNIDADES[self.nome+"^"+str(e)]
    if self != self.unidade_pai and self.expoente_pai != 1:
        return self.unidade_pai.nova_unidade_por_expoente(self.expoente_pai*e)

    # Decida como será o símbolo para o siunitx
    simbolo_siunitx = ""
    if self.simbolo_siunitx != "":
        simbolo_siunitx = self.simbolo_siunitx
        if abs(e) == 1:
            simbolo_siunitx += ""
        elif abs(e) == 2:
            simbolo_siunitx += "\\squared"
        elif abs(e) == 3:
            simbolo_siunitx += "\\cubed"
        else:
            simbolo_siunitx += "\\tothe{{{}}}".format(abs(e))

    # Gere a nova unidade
    cte_m = self.cte_multiplicativa**e
    cte_a = self.cte_aditiva
    dim = tuple([x*e for x in self.dimensao])
    u = Unidade(self.nome+"^"+str(e), self.simbolo+gera_expoente(e), self.simbolo_latex+"^"+str(e), dim, cte_m, cte_a, simbolo_siunitx)
    u.unidade_pai = self
    u.expoente_pai = e
    return u

def __pow__(self, outro):
    if not isinstance(outro, Medida):
        return self.__pow__(Medida(outro))

    if outro.dimensao != (0, 0, 0, 0, 0, 0, 0):
        raise NotImplementedError("o expoente deve ser adimensional")

    unidades = []
    if outro.nominal == int(outro.nominal) or (1/outro.nominal) == int(1/outro.nominal):
        for u in self.unidades_originais:
            unidades.append(u.nova_unidade_por_expoente(outro.nominal))
        unidades = simplifica_unidades(unidades)
    else:
        unidades = simplifica_unidades(self.unidades_originais)

    A = self.nominal
    B = outro.nominal
    # s = σ
    sA = self.incerteza
    sB = outro.incerteza
    sAB = sA*sB # Não tenho certeza se esse valor está certo

    f = self.nominal ** outro.nominal
    sf = 0
    sf += ((B/A)*sA)**2
    sf += (math.log(math.fabs(A))*sB)**2
    sf += 2*B*math.log(math.fabs(A))*sAB/A
    sf = math.fabs(f)*math.sqrt(math.fabs(sf))
    return Medida((f, sf), unidades)

def inicializa(self, valor, unidade_txt=None):
    # Analise o valor
    if isinstance(valor, Medida):
        self.nominal = valor.nominal
        self.incerteza = valor.incerteza
    elif isinstance(valor, str):
        self.nominal, self.incerteza = analisa_numero(valor)
    elif isinstance(valor, tuple) and len(valor) == 2:
        self.nominal, self.incerteza = float(valor[0]), abs(float(valor[1]))
    else:
        try:
            self.nominal = float(valor)
        except:
            raise Exception("não foi possível extrair o valor e a incerteza")

    # Veja as unidades
    if isinstance(unidade_txt, list):
        self.unidades_originais = copy(unidade_txt)
    elif unidade_txt != None:
        self.unidades_originais = analisa_unidades(unidade_txt)
    self.dimensao = calcula_dimensao(self.unidades_originais)

    # Converta para o SI
    mul_nom, mul_err, add_nom, add_err = fator_de_conversao_para_si(self.unidades_originais)
    self.si_nominal = self.nominal * mul_nom + add_nom
    self.si_incerteza = (self.nominal * mul_err + mul_nom * self.incerteza)  + add_err

def simplifica_unidades(la, lb_=[], inverte=False):
    lb = lb_
    if inverte == True:
        lb = []
        for i, u in enumerate(lb_):
            lb.append(u.nova_unidade_por_expoente(-1))
    l_unidades = la + lb


    d = {} # Dicionário Unidade-Expoente
    for u in l_unidades:
        u2 = u.unidade_pai
        if u.expoente_pai == 1 or u.expoente_pai == 0:
            u2 = u
        if u2 in d:
            d[u2] += u.expoente_pai
        else:
            d[u2] = u.expoente_pai
    pos = [] # Parte com expoentes positivos
    neg = [] # Parte com expoentes negativos
    for u, e in d.items():
        u2 = u.nova_unidade_por_expoente(e)
        if u2 is None:
            continue
        if e >= 1:
            pos.append(u2)
        elif e <= 1:
            neg.append(u2)
        else:
            pass # Não coloque nada com expoente zero
    pos.sort(key=lambda u: u.simbolo)
    neg.sort(key=lambda u: u.simbolo)
    return pos+neg

