        if item.__name__ == name:
            doc = inspect.getdoc(item)
            try:
                model_spec = docparser.parse_from_docstring(doc, spec='schema')
                if model_spec:
                    cls.schema_spec.append(model_spec)
                    settings.add_schema(name, cls)
                    if hasattr(cls, 'Meta'):
                        if hasattr(cls.Meta, 'example'):
