def _process_list():
    if len(item) == 1:
        return self[item[0]]
    trunk, *branches = item
    nd = NestedDict(self[trunk], root=False)
    return nd[branches] if len(branches) > 1 else nd[branches[0]]

def _process_list():
    *branches, tip = branch_key

    if self[tip]:
        if isinstance(self[tip], tuple):
            if isinstance(self[branches], tuple):
                raise KeyError('ambiguous keys={!r}'.format(branch_key))
            else:
                self[branches][tip] = value
        else:
            self[tip] = value
    else:
        raise KeyError('no key found={!r}'.format(tip))

def anchor(self, trunk, branch, value=None):
    nd = NestedDict(root=False)
    for k, v in self._val.items():
        if v and isinstance(v, dict):
            nd._val = self._val[k]
            nd.anchor(trunk, branch, value)
            self._found = self._found or nd._found

        if k == trunk:
            self._found = True
            if not isinstance(self._val[trunk], dict):
                if self._val[trunk]:
                    raise ValueError('value of this key is not a logical False')
                else:
                    self._val[trunk] = {}  # replace None, [], 0 and False to {}
            self._val[trunk][branch] = value

    if self._root:
        if self._found:
            self._found = False
        else:
            raise KeyError

def setdefault(self, key, default=None):

    if isinstance(key, list) or isinstance(key, tuple):
        # TODO tests this
        trunk, *branches = key

        self._val.setdefault(trunk, {})
        if self._val[trunk]:
            pass
        else:
            self._val[trunk] = default

        nd = NestedDict(self[trunk], root=False)
        if len(branches) > 1:
            nd[branches] = default
        elif len(branches) == 1:
            nd._val[branches[0]] = default
        else:
            raise KeyError
    else:
        self._val.setdefault(key, default)

def asciify(d: dict, is_root=True, al=list, lvl=0):
    if is_root:
        al = []
        lvl = 0

    if d:
        for k, v in d.items():
            il = []
            for i in range(lvl):
                if i == lvl - 1:
                    il.append('`-- ')
                else:
                    il.append('    ')
            il.append(k)
            al.append(il)

            if d[k]:
                lvl += 1
                al = asciify(d[k], is_root=False, al=al, lvl=lvl)
                lvl -= 1

    if is_root:
        empt_fill = '    '
        vert_fill = '|   '
        end__fill = '`-- '
        plus_fill = '+-- '

        replacement = set()
        for each_line in reversed(al):

            to_remove = []
            for index in replacement:
                if each_line[index] == empt_fill:
                    each_line[index] = vert_fill
                elif each_line[index] == end__fill:
                    each_line[index] = plus_fill
                else:
                    to_remove.append(index)

            while to_remove:
                replacement.discard(to_remove.pop())

            for i, e in enumerate(each_line):
                if e == end__fill:
                    replacement.add(i)

        sl = [''.join(x) for x in al]

        return sl
    else:
        return al

def __init__ (self, dbname, code_size=4, init_code=None):
    """Class initialiser."""
    self.engine = create_engine(dbname)
    self.code_size = code_size
    self.init_code = init_code
    if init_code is None:
        self.init_code = AlphaNumCodeManager.Alphabet[0] * self.code_size
    self.alphabet_map = {j: i for i, j in enumerate(AlphaNumCodeManager.Alphabet)}
    self.alphabet_size = len(self.alphabet_map)

    if len(self.init_code) != self.code_size:
        raise ValueError("code_size (%d) does not fit init_code length (%d)" % (self.code_size, len(self.init_code)))

    AlphaNumCodeManager.Base.metadata.create_all(self.engine)
    Session = sessionmaker(bind=self.engine)
    self.session = Session()

    last_record = self._get_last_record()
    if last_record is not None:
        if len(last_record) != self.code_size:
            raise ValueError("code_size (%d) does not fit length of existing codes (%d) in %s" % (self.code_size, len(last_record), dbname))

def _calculate_next_code(self, code):
    """Return newly calculated code based on provided code.

    Args:
        code (str): code used to calculate the next one

    Returns:
        str: calculated new code
    """
    reverse_new_code_ints = [self.alphabet_map[char] for char in code[::-1]]
    reverse_new_code_ints[0] += 1
    for i, new_code_int in enumerate(reverse_new_code_ints):
        if new_code_int >= self.alphabet_size:
            if i >=  self.code_size - 1:
                raise StopIteration("Last code reached")
            else:
                reverse_new_code_ints[i] = 0
                reverse_new_code_ints[i + 1] += 1
    next_code = [AlphaNumCodeManager.Alphabet[new_code_int] for new_code_int in reverse_new_code_ints[::-1]]
    return "".join(next_code)

