def indent_string(string, level=1, spacing='    '):
    if string is None:
        return ''

    lines = []

    for line in string.split('\n'):
        if line:
            lines.append(spacing * level + line)
    output = '\n'.join(lines) + '\n'

    return output

def get_depth_of_file(file_name: str):
