        file_name = file_name[2:]

    return len(file_name.split('/'))

def add(self, val):
    prev_count = self._max_point[0]
    self._max_point[0] = prev_count + 1

    cur_min, cur_max = self._min_point[1], self._max_point[1]
    if val < cur_min:
        self._min_point[1] = cur_min = val
    elif val > cur_max:
        self._max_point[1] = cur_max = val

    for point, nxt_point in self._back_tuples:
        if val <= point[1]:
            point[0] += 1
            if point[0] == nxt_point[0]:
                point[0] -= 1

    # update estimated locations of percentiles
    for qpdiv, (ln, lq), cur, (rn, rq) in self._quads:
        cn, cq = cur
        d = int(prev_count * qpdiv + 1 - cn)
        if not d:
            continue
        d = 1.0 if d > 0 else -1.0  # clamped at +-1
        if not (ln < cn + d < rn):
            continue
        nq = (cq + (d / (rn - ln)) *  # hooray parabolic
              ((cn - ln + d) * (rq - cq) / (rn - cn) +
               (rn - cn - d) * (cq - lq) / (cn - ln)))
        if not (lq < nq < rq):  # fall back on linear eqn
            if d == 1:
                nq = cq + (rq - cq) / (rn - cn)
            else:
                nq = cq - (lq - cq) / (ln - cn)
        cur[0], cur[1] = cn + d, nq

def add(self, val):
    if self._count < self._cap:
        self._data.append(val)
        self._is_sorted = False
        super(ReservoirAccumulator, self).add(val)
    else:
        # TODO: randint has a lot of pure-python arg checking
        # machinery we don't need
        idx = random.randint(0, self._count)
        if idx < self._cap:
            self._data[idx] = val
            self._is_sorted = False
            super(ReservoirAccumulator, self).add(val)

def add(self, val):
    if self._est is None:
        ta = self._tmp_acc
        ta.add(val)
        if ta.count >= self._thresh:
            self._est = P2Estimator(self._q_points, ta._data)
            self._tmp_acc = None
        return
    else:
        self._est.add(val)
    super(P2Accumulator, self).add(val)

