@staticmethod
def _process_q_points(q_points):
    try:
        qps = sorted([float(x) for x in set(q_points or [])])
        if qps[0] == 0.0:
            qps = qps[1:]
        if qps[-1] == 1.0:
            qps = qps[:-1]
        if not qps or not all([0.0 < x < 1.0 for x in qps]):
            raise ValueError()
    except Exception:
        raise ValueError('invalid quantile point(s): %r' % (q_points,))
    else:
        return tuple(qps)

def _get_quantile(self, q=0.5):
    if not (0.0 < q < 1.0):
        raise ValueError('expected a value in range 0.0 - 1.0 (non-inclusive)')
    self._sort()
    data, n = self._data, len(self._data)
    idx = q * (n - 1)
    idx_f, idx_c = int(floor(idx)), int(ceil(idx))
    if idx_f == idx_c:
        return data[idx_f]
    return (data[idx_f] * (idx_c - idx)) + (data[idx_c] * (idx - idx_f))

def _sort(self):
    if self._is_sorted:
        return
    if callable(getattr(self._data, 'sort', None)):
        self._data.sort()
    else:
        self._data = array.array(self._typecode, sorted(self._data))
    self._is_sorted = True

