def _get_syslog_priority(self, event_name, action):
    level = get_level(action.level)

    if event_name == 'warn':
        status = 'warn'
    elif event_name == 'begin':
        status = 'begin'
    else:
        status = action.status
    return self.priority_map[level][status]

