def unwrap(target, attr_name):
    wrapped_func = getattr(target, attr_name)
    try:
        unwrapped_func = wrapped_func.__lithoxyl_wrapped__[3]
    except Exception:
        raise ValueError('%r does not appear to be a wrapped function'
                         % wrapped_func)
    setattr(target, attr_name, unwrapped_func)
    return

def unwrap_all(target=None):
    if target is None or isinstance(target, int):
        target = target or 1
        try:
            target_module_name = sys._getframe(target).f_globals.__name__
            calling_module = sys.modules[target_module_name]
        except Exception:
            raise ValueError('unable to wrap all with target: %r' % target)
        target = calling_module

    unwrapped = set()

    def unwrap_sub_target(sub_target):
        for attr_name in dir(sub_target):
            try:
                val = getattr(sub_target, attr_name)
            except AttributeError:
                continue
            if not callable(val):
                continue
            elif isinstance(val, type_types):
                if id(val) in unwrapped:
                    continue
                unwrapped.add(id(val))
                unwrap_sub_target(val)
            else:
                try:
                    unwrap(sub_target, attr_name)
                except ValueError:
                    continue
        return

    unwrap_sub_target(target)
    return

def modify(self, indexed_by, value, new_value):
    # modify must modify the obj only when every index property is satisfied.
    modifier = MultiIndexModifier()
    old_obj = self.get(indexed_by, value)

    if isinstance(old_obj, (list, tuple)):
        old_obj = old_obj[0]
    obj = copy.copy(old_obj)
    setattr(obj, indexed_by, new_value)
    can_be_modified = [index.can_be_modified(modifier, obj) for index in self.indexes.values()
                       if index.index_name == indexed_by]
    if all(can_be_modified):
        for index in self.indexes.values():
            index.modify(getattr(old_obj, index.index_name), obj)

def remove(self, indexed_by, value):
    # insert must only insert the obj only when every index property is satisfied.
    index = self.indexes.get(indexed_by)
    assert index, 'Index provided does not exists in Container'
    obj = index.get(value)
    if isinstance(obj, (list, tuple)):
        obj = obj[0]

    deleter = MultiIndexDeleter()
    can_be_removed = [index.can_be_removed(deleter, obj) for index in self.indexes.values()]
    if all(can_be_removed):
        for index in self.indexes.values():
            index.remove(getattr(obj, index.index_name))

